  imp_read_volley_fields: { en: 'Clear fields give archers unbroken lanes of fire', es: 'Los campos despejados dan a los arqueros líneas de tiro', ru: 'Чистые поля дают лучникам линии огня', mk: 'Чистите полиња им даваат линии на оган на стрелците', de: 'Freie Felder geben Bogenschützen offene Schusslinien', fr: 'Les champs dégagés offrent aux archers des lignes de tir' },
  imp_read_volley_cover: { en: 'Mountain cover swallows the arrows', es: 'La cobertura montañosa se traga las flechas', ru: 'Горное укрытие поглощает стрелы', mk: 'Планинскиот заклон ги голта стрелите', de: 'Bergdeckung schluckt die Pfeile', fr: 'Le couvert montagneux avale les flèches' },
