  imp_help: { en: 'How to play', es: 'Cómo se juega', ru: 'Как играть', mk: 'Како се игра', de: 'Spielanleitung', fr: 'Comment jouer' },
  imp_tut_1_t: { en: '1 · Command your armies', es: '1 · Comanda tus ejércitos', ru: '1 · Командуйте армиями', mk: '1 · Командувај со војските', de: '1 · Befehlige deine Armeen', fr: '1 · Commande tes armées' },
  imp_tut_1_b: { en: 'Tap one of your gold armies, then tap any province to order a march. The dashed line shows the exact route it will take.', es: 'Toca uno de tus ejércitos dorados y luego una provincia para ordenar la marcha. La línea discontinua muestra la ruta exacta.', ru: 'Нажмите на свою золотую армию, затем на провинцию — армия выступит. Пунктир показывает точный маршрут.', mk: 'Допри една од твоите златни војски, па допри провинција за марш. Испрекинатата линија го покажува точниот пат.', de: 'Tippe auf eine deiner goldenen Armeen und dann auf eine Provinz, um den Marsch zu befehlen. Die gestrichelte Linie zeigt die genaue Route.', fr: "Touche une de tes armées dorées, puis une province pour ordonner la marche. La ligne pointillée montre l'itinéraire exact." },
  imp_tut_2_t: { en: '2 · Pick a tactic', es: '2 · Elige una táctica', ru: '2 · Выберите тактику', mk: '2 · Избери тактика', de: '2 · Wähle eine Taktik', fr: '2 · Choisis une tactique' },
  imp_tut_2_b: { en: 'Charge beats Volley, Volley beats Shield Wall, Shield Wall beats Charge. Your tactic applies to every battle this turn.', es: 'La carga vence a la descarga, la descarga al muro de escudos y el muro a la carga. Tu táctica se aplica a todas las batallas del turno.', ru: 'Атака бьёт залп, залп бьёт стену щитов, стена щитов бьёт атаку. Тактика действует во всех битвах хода.', mk: 'Јуришот победува салва, салвата штитен ѕид, а ѕидот јуриш. Тактиката важи за секоја битка овој потег.', de: 'Sturmangriff schlägt Salve, Salve schlägt Schildwall, Schildwall schlägt Sturmangriff. Deine Taktik gilt für jede Schlacht dieser Runde.', fr: 'La charge bat la salve, la salve bat le mur de boucliers, le mur bat la charge. Ta tactique vaut pour chaque bataille du tour.' },
  imp_tut_3_t: { en: '3 · Guard your supply lines', es: '3 · Protege tus suministros', ru: '3 · Берегите снабжение', mk: '3 · Чувај го снабдувањето', de: '3 · Sichere deinen Nachschub', fr: '3 · Protège ton ravitaillement' },
  imp_tut_3_b: { en: 'Armies must trace a friendly path back to your capital. If the enemy cuts it, they starve — losses compound every turn.', es: 'Los ejércitos deben trazar un camino amigo hasta tu capital. Si el enemigo lo corta, pasan hambre — las pérdidas se agravan cada turno.', ru: 'Армии должны иметь дружественный путь к столице. Если враг его перережет — начнётся голод, и потери будут расти с каждым ходом.', mk: 'Војските мора да имаат пријателски пат до престолнината. Ако непријателот го пресече, гладуваат — загубите растат секој потег.', de: 'Armeen brauchen einen freundlichen Weg zurück zur Hauptstadt. Kappt ihn der Feind, hungern sie — die Verluste wachsen jede Runde.', fr: "Les armées doivent garder un chemin ami vers ta capitale. Si l'ennemi le coupe, elles meurent de faim — les pertes s'aggravent chaque tour." },
  imp_tut_4_t: { en: '4 · Take every rival province', es: '4 · Toma todas las provincias rivales', ru: '4 · Захватите все провинции врага', mk: '4 · Земи ги сите ривалски провинции', de: '4 · Nimm jede gegnerische Provinz', fr: '4 · Prends toutes les provinces rivales' },
  imp_tut_4_b: { en: 'March into neutral provinces to claim them freely. Win the campaign by holding everything your rival started with — and beware crises along the way.', es: 'Entra en provincias neutrales para reclamarlas sin lucha. Gana la campaña controlando todo lo que tu rival tenía al empezar — y cuidado con las crisis por el camino.', ru: 'Нейтральные провинции занимаются без боя. Победа — когда всё, с чем начинал соперник, ваше. И берегитесь кризисов по пути.', mk: 'Влези во неутрални провинции за да ги заземеш слободно. Победи ја кампањата држејќи сè со што почна ривалот — и внимавај на кризите попат.', de: 'Marschiere in neutrale Provinzen, um sie kampflos zu beanspruchen. Gewinne den Feldzug, indem du alles hältst, womit dein Rivale begann — und hüte dich vor Krisen.', fr: 'Entre dans les provinces neutres pour les prendre sans combat. Gagne la campagne en tenant tout ce que possédait ton rival — et gare aux crises en chemin.' },
  imp_got_it: { en: 'To battle!', es: '¡A la batalla!', ru: 'В бой!', mk: 'Во битка!', de: 'In die Schlacht!', fr: 'Au combat !' },
  imp_battlefield: { en: 'Battlefield', es: 'Campo de batalla', ru: 'Поле боя', mk: 'Бојно поле', de: 'Schlachtfeld', fr: 'Champ de bataille' },
  imp_new_here: { en: 'A new campaign will open on this theatre\'s living map.', es: 'Una nueva campaña se abrirá sobre el mapa vivo de este teatro.', ru: 'Новая кампания развернётся на живой карте этого театра.', mk: 'Нова кампања ќе се отвори на живата карта на овој театар.', de: 'Ein neuer Feldzug beginnt auf der lebenden Karte dieses Schauplatzes.', fr: 'Une nouvelle campagne s\'ouvrira sur la carte vivante de ce théâtre.' },
